SELECT CASE WHEN grading_kind='R' THEN reassessment_event_id ELSE 'GRADE:'||assignment_id||':'||instructor_id||':'||grading_time END event_id,instructor_id case_id,CASE WHEN grading_kind='R' THEN 'Assignment Regraded' ELSE 'Assignment Graded' END activity,grading_time timestamp FROM assignment_grading WHERE grading_time IS NOT NULL AND grading_kind IN ('A','R') ORDER BY case_id,timestamp,event_id;
